import { Component, OnInit } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-padre',
  templateUrl: './padre.component.html',
  styleUrls: ['./padre.component.css']
})
export class PadreComponent implements OnInit{

  public totalCompras : number = 0;
  public ultimoPrecio: number = 0;  // Añadido para almacenar el precio de la última compra.
  public misCompras: MisCompras[] = [];

  constructor(public misComprasService: MisComprasService, public usuarioService: UsuarioService){}

  ngOnInit(): void {
    this.cargarCompras();
  }

  cargarCompras(){
    const email = this.usuarioService.obtenerEmailUsuarioLogeado();
    this.misComprasService.obtenerComprasUsuario(email).subscribe( compras => {
      this.misCompras = compras;
      this.calcularTotalCompras();
    });
  }


  calcularTotalCompras(){
    this.totalCompras = this.misCompras.reduce((acc, compra) => acc + compra.total, 0);
    if(this.misCompras.length > 0){
      this.ultimoPrecio = this.misCompras[this.misCompras.length -1].total;
    }
  }

}
